<?php
require __DIR__.'/config/database.php'; require __DIR__.'/config/helpers.php';
$estados=['Pendiente','En proceso','Terminado','Entregado']; $tipos=['Alternador','Marcha / motor de arranque','Cableado','Sistema eléctrico','Otro']; $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 check_csrf(); $accion=$_POST['accion']??'crear';
 if($accion==='estado') {
  $id=filter_var($_POST['orden_id']??'',FILTER_VALIDATE_INT); $estado=$_POST['estado']??'';
  if(!$id || !in_array($estado,$estados,true)) $error='Estado inválido.';
  else { $st=$pdo->prepare('UPDATE ordenes SET estado=? WHERE id=?'); $st->execute([$estado,$id]); redirect_saved('ordenes.php'); }
 } else {
  $vehiculo=filter_var($_POST['vehiculo_id']??'',FILTER_VALIDATE_INT); $tipo=$_POST['tipo_servicio']??'';
  $falla=trim($_POST['falla_reportada']??''); $diag=trim($_POST['diagnostico']??''); $rep=trim($_POST['reparacion']??'');
  $costos=[];
  foreach(['costo_refacciones','costo_mano_obra','anticipo'] as $campo) { $valor=trim((string)($_POST[$campo]??'0')); if(!is_numeric($valor) || (float)$valor<0 || (float)$valor>99999999) $error='Los importes deben ser números positivos.'; $costos[$campo]=(float)$valor; }
  if(!$vehiculo || !in_array($tipo,$tipos,true) || $falla==='' || mb_strlen($falla)>5000 || mb_strlen($diag)>5000 || mb_strlen($rep)>5000) $error='Revisa el vehículo, tipo de servicio y descripción de falla.';
  if($costos['anticipo']>$costos['costo_refacciones']+$costos['costo_mano_obra']) $error='El anticipo no puede superar el total.';
  if(!$error) { $st=$pdo->prepare('SELECT COUNT(*) FROM vehiculos WHERE id=?'); $st->execute([$vehiculo]); if(!$st->fetchColumn()) $error='Selecciona un vehículo válido.'; }
  if(!$error) { $st=$pdo->prepare('INSERT INTO ordenes (vehiculo_id,tipo_servicio,falla_reportada,diagnostico,reparacion,costo_refacciones,costo_mano_obra,anticipo) VALUES (?,?,?,?,?,?,?,?)'); $st->execute([$vehiculo,$tipo,$falla,$diag,$rep,$costos['costo_refacciones'],$costos['costo_mano_obra'],$costos['anticipo']]); redirect_saved('ordenes.php'); }
 }
}
$vehiculos=$pdo->query('SELECT v.id,v.marca,v.modelo,c.nombre FROM vehiculos v JOIN clientes c ON c.id=v.cliente_id ORDER BY c.nombre,v.marca')->fetchAll();
$ordenes=$pdo->query('SELECT o.*,v.marca,v.modelo,c.nombre AS cliente FROM ordenes o JOIN vehiculos v ON v.id=o.vehiculo_id JOIN clientes c ON c.id=v.cliente_id ORDER BY o.id DESC')->fetchAll();
page_top('Órdenes de trabajo'); ?>
<p class="muted">Servicios eléctricos: alternadores, marchas, cableado y diagnóstico automotriz.</p><section class="columns"><article class="panel"><h2>Nueva orden</h2><?php if($error): ?><p class="error"><?=h($error)?></p><?php endif; ?>
<?php if(!$vehiculos): ?><p>Primero registra un vehículo en <a href="vehiculos.php">Vehículos</a>.</p><?php else: ?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="accion" value="crear"><label>Vehículo<select name="vehiculo_id" required><option value="">Seleccionar vehículo</option><?php foreach($vehiculos as $v): ?><option value="<?=(int)$v['id']?>" <?=((int)($_GET['vehiculo_id']??0)===(int)$v['id'])?'selected':''?>><?=h($v['marca'].' '.$v['modelo'].' · '.$v['nombre'])?></option><?php endforeach; ?></select></label><label>Tipo de trabajo<select name="tipo_servicio" required><?php foreach($tipos as $tipo): ?><option value="<?=h($tipo)?>"><?=h($tipo)?></option><?php endforeach; ?></select></label><label>Falla reportada<textarea name="falla_reportada" required maxlength="5000" placeholder="Ej. No carga la batería"></textarea></label><label>Diagnóstico<textarea name="diagnostico" maxlength="5000"></textarea></label><label>Reparación realizada / prevista<textarea name="reparacion" maxlength="5000"></textarea></label><label>Costo de refacciones ($)<input type="number" name="costo_refacciones" min="0" max="99999999" step="0.01" value="0" required></label><label>Mano de obra ($)<input type="number" name="costo_mano_obra" min="0" max="99999999" step="0.01" value="0" required></label><label>Anticipo ($)<input type="number" name="anticipo" min="0" max="99999999" step="0.01" value="0" required></label><button>Guardar orden</button></form><?php endif; ?></article>
<article class="panel"><h2>Órdenes registradas</h2><?php if(!$ordenes): ?><p class="muted">Todavía no hay órdenes.</p><?php else: ?><?php foreach($ordenes as $o): ?><div class="order"><b>OT-<?=str_pad((string)$o['id'],4,'0',STR_PAD_LEFT)?> · <?=h($o['tipo_servicio'])?></b><p><?=h($o['marca'].' '.$o['modelo'].' · '.$o['cliente'])?></p><p><strong>Falla:</strong> <?=nl2br(h($o['falla_reportada']))?></p><?php if($o['diagnostico']): ?><p><strong>Diagnóstico:</strong> <?=nl2br(h($o['diagnostico']))?></p><?php endif; ?><?php if($o['reparacion']): ?><p><strong>Reparación:</strong> <?=nl2br(h($o['reparacion']))?></p><?php endif; ?><p><strong>Total:</strong> <?=money($o['costo_refacciones']+$o['costo_mano_obra'])?> · <strong>Anticipo:</strong> <?=money($o['anticipo'])?> · <strong>Saldo:</strong> <?=money($o['costo_refacciones']+$o['costo_mano_obra']-$o['anticipo'])?></p><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="accion" value="estado"><input type="hidden" name="orden_id" value="<?=(int)$o['id']?>"><label>Estado<select name="estado"><?php foreach($estados as $estado): ?><option value="<?=h($estado)?>" <?=$o['estado']===$estado?'selected':''?>><?=h($estado)?></option><?php endforeach; ?></select></label><button>Actualizar estado</button></form></div><?php endforeach; ?><?php endif; ?></article></section><?php page_bottom(); ?>
